// WATCH_TARGETS: "name|url,name|url"
const raw = $env.WATCH_TARGETS || '';
return raw
  .split(',')
  .map((entry) => entry.trim())
  .filter(Boolean)
  .map((entry) => {
    const [name, url] = entry.includes('|') ? entry.split('|') : [entry, entry];
    const host = url.trim().replace(/^[a-z]+:\/\//i, '').split(/[/:?#]/)[0];
    return { json: { name: name.trim(), url: url.trim(), host } };
  });

// Compare this run with the previous one (kept in workflow static data)
// and emit a single item only when something changed.
const targets = $('Targets').all().map((item) => item.json);
const checks = $('Check').all().map((item) => item.json);
const dns = $input.all().map((item) => item.json);
const state = $getWorkflowStaticData('global');
state.targets = state.targets || {};

const alerts = [];
const now = new Date().toISOString();

targets.forEach((target, i) => {
  const check = checks[i] || {};
  const status = typeof check.statusCode === 'number' ? check.statusCode : null;
  const up = status !== null && status >= 200 && status < 400;
  const detail = status !== null ? `HTTP ${status}` : (check.error && check.error.message) || 'no response';
  const ips = ((dns[i] && dns[i].Answer) || [])
    .filter((answer) => answer.type === 1)
    .map((answer) => answer.data)
    .sort();

  const prev = state.targets[target.name];
  const base = { target: target.name, url: target.url };
  if (!prev) {
    if (!up) alerts.push({ ...base, event: 'DOWN', detail });
  } else {
    if (prev.up && !up) alerts.push({ ...base, event: 'DOWN', detail });
    if (!prev.up && up) alerts.push({ ...base, event: 'RECOVERED', detail });
    if (ips.length && prev.ips.length && ips.join(',') !== prev.ips.join(',')) {
      alerts.push({ ...base, event: 'IP_CHANGED', detail: `${prev.ips.join(', ')} -> ${ips.join(', ')}` });
    }
  }
  state.targets[target.name] = { up, ips: ips.length ? ips : (prev ? prev.ips : []), checkedAt: now };
});

if (!alerts.length) return [];
const text = alerts.map((a) => `[${a.event}] ${a.target} (${a.url}): ${a.detail}`).join('\n');
return [{ json: { alerts, text, checkedAt: now } }];

// Use Claude's summary when the call succeeded, otherwise send the raw alerts.
const incident = $('Detect changes').first().json;
const ai = $input.first().json;
const summary = ai && ai.content && ai.content[0] && ai.content[0].text;
const message = [`Server Watch alert (${incident.checkedAt})`, incident.text, summary ? `\nSummary:\n${summary}` : '']
  .filter(Boolean)
  .join('\n');
return [{ json: { message } }];
